import{_ as e,c as t,o as s,a}from"./app.19f3f8f0.js";const m=JSON.parse('{"title":"Episode 4 — Your automation has an end date","description":"Match automation to real promos—turn off DMs when the sale or event is over.","frontmatter":{"title":"Episode 4 — Your automation has an end date","description":"Match automation to real promos—turn off DMs when the sale or event is over."},"headers":[{"level":2,"title":"Why creators like this","slug":"why-creators-like-this","link":"#why-creators-like-this","children":[]},{"level":2,"title":"Series","slug":"series","link":"#series","children":[]}],"relativePath":"replybridge/series/04-automation-end-date.md"}'),o={name:"replybridge/series/04-automation-end-date.md"},r=a('<h1 id="episode-4-—-your-automation-has-an-end-date-on-purpose" tabindex="-1">Episode 4 — Your automation has an end date (on purpose) <a class="header-anchor" href="#episode-4-—-your-automation-has-an-end-date-on-purpose" aria-hidden="true">#</a></h1><p>Sales and launches <strong>end</strong>. Your automation should too—otherwise old posts keep promising deals you no longer run.</p><p>ReplyBridge lets you set a <strong>shared end time</strong> for Auto DM and public reply on a post. When time’s up, automation <strong>stops</strong> and you get a clear signal to check the app.</p><hr><h2 id="why-creators-like-this" tabindex="-1">Why creators like this <a class="header-anchor" href="#why-creators-like-this" aria-hidden="true">#</a></h2><ul><li>No awkward “sorry, that promo ended” DMs weeks later.</li><li><strong>Event posts</strong> and <strong>seasonal drops</strong> stay tidy.</li><li>You can <strong>extend</strong> in the app when it makes sense (where the app offers that option).</li></ul><hr><h2 id="series" tabindex="-1">Series <a class="header-anchor" href="#series" aria-hidden="true">#</a></h2><ul><li><strong>Previous:</strong> <a href="/replybridge/series/03-keywords-once">Episode 3</a></li><li><strong>Next:</strong> <a href="/replybridge/series/05-sales-and-events">Episode 5 — Sales &amp; events</a></li><li><strong>All episodes:</strong> <a href="/replybridge/series/">Instagram mini-series</a></li></ul>',9),n=[r];function i(d,l,h,p,u,c){return s(),t("div",null,n)}const _=e(o,[["render",i]]);export{m as __pageData,_ as default};
